export const goldQuestions = evaluationStories.flatMap((story) =>
  goldQuestionTemplates.map((question) => ({
    ...question,
    id: `${story.id}/${question.id}`,
    caseId: question.id,
    storyId: story.id,
    text: question.text
      .replaceAll('{artifact}', story.artifact)
      .replaceAll('{actorA}', story.actors[0])
      .replaceAll('{actorB}', story.actors[1])
      .replaceAll('{skill}', story.skill),
  })),
);
